/** The three triage signals. Kept in step with the CHECK in db/002_signals.sql. */
export const SIGNAL_KINDS = ["needs-check", "looks-wrong", "dead-link"];

/**
 * Is this an entry that actually exists?
 *
 * An allowlist rather than a pattern. A shape check would let a signal or a proposal be
 * filed against an id nobody can navigate to, which is invisible rather than harmless:
 * the row is real, it counts, and no page will ever show it so nobody can dispute it.
 */
export function isEntryId(v) {
  return typeof v === "string" && ENTRY_IDS.has(v);
}

export function isSignalKind(v) {
  return SIGNAL_KINDS.includes(v);
}

/**
 * The grades an entry currently carries, as {verification, autonomy}, or null.
 *
 * Enough to refuse a grade challenge that proposes the grade already set. Deliberately
 * not enough to render anything: the registry is served from data/entries.json and the
 * pre-built HTML, and a second copy of it here would be a second thing to keep in step.
 */
export function entryGrades(id) {
  const g = Object.hasOwn(ENTRY_GRADES, id) ? ENTRY_GRADES[id] : null;
  return g ? { verification: g[0], autonomy: g[1] } : null;
}

/**
 * An entry's title, or null.
 *
 * Object.hasOwn rather than a plain lookup, here and above: a bare `ENTRY_TITLES[id]`
 * with id set to "constructor" or "toString" returns something truthy off the
 * prototype, and this value is rendered.
 */
export function entryTitle(id) {
  return Object.hasOwn(ENTRY_TITLES, id) ? ENTRY_TITLES[id] : null;
}
